def sliding_count(I,t):
    H,W=len(I),len(I[0]); bg=None
    cnts=Counter()
    for r in range(H-2):
        for q in range(W-2):
            match=True
            for dr,dc in t:
                a,b=r+dr,q+dc
                if a>=H or b>=W: match=False;break
                v=I[a][b]
                if bg is None:bg=max(set(v for row in I for v in row),key=lambda k:sum(row.count(k) for row in I))
                if v==bg: match=False;break
            if match: cnts[(r,q)]+=1
    return cnts,max(cnts.values()) if cnts else (0,0)
