                while st:
                    a,b=st.pop();comp.append((a,b))
                    for d in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+d[0],b+d[1]
                        if 0<=x<H and 0<=y<W and I[x][y]==c and (x,y) not in seen:
